// Bozulan workflow'un bilgilerini okunur bir uyarıya çevirir ve
// local-files/hatalar.json içine son 200 kaydı tutar.
//
// ÖNEMLİ: bu workflow bir NÖBETÇİdir — kendisi asla durmamalı. Bu yüzden
// hatalar.json bozuksa hata fırlatmak yerine yazmayı atlar, bildirimi yine
// gönderir ve mesajın sonuna bir uyarı satırı ekler.
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));

const olay = $('Hata Yakalandı').first().json || {};
const wf = olay.workflow || {};
const ex = olay.execution || {};
const hata = ex.error || olay.error || {};

const simdi = new Date();
const zamanMetni = simdi.toLocaleString('tr-TR', {
  day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit',
});

const wfAdi = wf.name || 'Bilinmeyen workflow';
const dugum = ex.lastNodeExecuted || hata.node || '';
const mesaj = String(hata.message || 'Hata mesajı yok').split('\n')[0].slice(0, 400);
const calistirmaUrl = ex.url || (ex.id ? 'http://localhost:5678/workflow/' + (wf.id || '') + '/executions/' + ex.id : '');

// ── Geçmişe ekle (bozuksa atla) ──────────────────────────────────────────────
let hatalar = [];
let yazilsin = true;
let uyari = '';
const okuHata = $('Hataları Oku').first().json.error;
const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
const cikarHata = $('Hataları Çıkar').first().json.error;
const dosyaYok = /ENOENT|no such file|not found/i.test(okuMesaj);
if (!dosyaYok && (okuHata || cikarHata)) {
  yazilsin = false;
  uyari = '\n⚠️ hatalar.json okunamadı, bu kayıt dosyaya yazılmadı.';
} else {
  const j = $('Hataları Çıkar').first().json || {};
  const d = (j.data && j.data.hatalar) || [];
  hatalar = Array.isArray(d) ? d.map((x) => ({ ...x })) : [];
}
if (yazilsin) {
  hatalar.push({
    tarih: simdi.toISOString(),
    workflow: wfAdi,
    workflowId: wf.id || null,
    dugum,
    mesaj,
    calistirma: ex.id || null,
  });
  if (hatalar.length > 200) hatalar = hatalar.slice(-200); // dosya şişmesin
}

// ── Aynı workflow bugün kaç kez patladı ─────────────────────────────────────
const gunBasi = new Date(simdi); gunBasi.setHours(0, 0, 0, 0);
const bugunAyni = hatalar.filter((h) =>
  h.workflow === wfAdi && new Date(h.tarih).getTime() >= gunBasi.getTime()).length;
const tekrar = bugunAyni > 1 ? '\n🔁 Bugün ' + bugunAyni + '. kez.' : '';

const satirlar = [
  '🚨 Workflow hatası',
  '',
  '📛 ' + wfAdi,
  dugum ? '🔧 Düğüm: ' + dugum : '',
  '🕒 ' + zamanMetni,
  '',
  '💬 ' + mesaj,
].filter(Boolean);
const text = satirlar.join('\n') + tekrar + uyari +
  (calistirmaUrl ? '\n\n🔗 ' + calistirmaUrl : '');

const html = '<div style="font-family:system-ui,sans-serif;line-height:1.5">' +
  '<h2>🚨 Workflow hatası</h2>' +
  '<p><b>' + esc(wfAdi) + '</b>' + (dugum ? ' — düğüm: <code>' + esc(dugum) + '</code>' : '') + '</p>' +
  '<p style="color:#b00">' + esc(mesaj) + '</p>' +
  '<p style="color:#666">' + esc(zamanMetni) + (tekrar ? ' · ' + esc(tekrar.trim()) : '') + '</p>' +
  (calistirmaUrl ? '<p><a href="' + esc(calistirmaUrl) + '">Çalıştırmayı aç</a></p>' : '') +
  (uyari ? '<p style="color:#b00">' + esc(uyari.trim()) + '</p>' : '') +
  '</div>';

return [{ json: {
  text, html, hatalar, yazilsin,
  konu: '🚨 n8n hatası: ' + wfAdi,
} }];

// Dosyaya yalnızca hata listesi yazılır (okuma bozulduysa hiç yazılmaz).
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: { hatalar: j.hatalar } }];

// Telegram kuruluysa uyarı oraya gider.
const j = $input.first().json;
const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chat = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!token || !chat) return [];
return [{ json: { chat_id: chat, text: j.text.slice(0, 3900) } }];

// Telegram kurulu DEĞİLSE uyarı mail olarak gider (çift bildirim olmasın).
const j = $input.first().json;
const kurulu = String($env.TELEGRAM_BOT_TOKEN || '').trim() && String($env.TELEGRAM_CHAT_ID || '').trim();
if (kurulu) return [];
return [{ json: { konu: j.konu, html: j.html } }];
